MOD = 1000000007

def read_ints():
    return list(map(int, input().split()))

def count_distinct_simple_paths(n, m, edges, xi, yi):
    # This function should count the number of distinct simple paths from xi to yi
    # in the given graph. For the sake of this task, let's assume we have a function
    # that can do this. We'll implement a simple DFS-based approach for demonstration.

    from collections import defaultdict, deque

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def dfs(node, target):
        stack = [(node, [])]
        visited = set()
        path_count = 0

        while stack:
            current, path = stack.pop()
            if current == target:
                path_count += 1
                path_count %= MOD
                continue
            if current in visited:
                continue
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    stack.append((neighbor, path + [current]))

        return path_count

    return dfs(xi, yi)

# Read input
n, m = read_ints()
edges = [read_ints() for _ in range(m)]
k = int(input())
interesting_pairs = [read_ints() for _ in range(k)]

# Calculate and print results
for xi, yi in interesting_pairs:
    result = count_distinct_simple_paths(n, m, edges, xi, yi)
    print(result)
